Solution A: function createSpaceInvaders(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d');const W=canvas.width;const H=canvas.height;let lastTime=0;let animationId;let level=1;let score=0;let gameOver=false;let win=false;const keys={};window.addEventListener('keydown',e=>keys[e.code]=true);window.addEventListener('keyup',e=>keys[e.code]=false);const player={w:40,h:20,x:W/2-20,y:H-30,speed:200,cooldown:0};const playerBullets=[];const enemyBullets=[];let enemies=[];let enemyDir=1;let enemySpeed=30;let enemyDescend=20;let enemyFireTimer=0;let explosions=[];function initEnemies(){enemies=[];const rows=5;const cols=10;const ew=30;const eh=20;const gapX=10;const gapY=15;const offsetX=(W-(cols*ew+ (cols-1)*gapX))/2;const offsetY=30;for(let r=0;r<rows;r++){for(let c=0;c<cols;c++){enemies.push({w:ew,h:eh,x:offsetX+c*(ew+gapX),y:offsetY+r*(eh+gapY)});}}enemyDir=1;enemySpeed=30+level*5;enemyFireTimer=0;}function update(dt){if(gameOver)return;player.cooldown-=dt;if(keys['ArrowLeft'])player.x-=player.speed*dt;if(keys['ArrowRight'])player.x+=player.speed*dt;player.x=Math.max(0,Math.min(W-player.w,player.x));if(keys['Space'] && player.cooldown<=0){playerBullets.push({x:player.x+player.w/2-2,y:player.y,w:4,h:10,dy:-300});player.cooldown=0.3;}playerBullets.forEach(b=>b.y+=b.dy*dt);enemyBullets.forEach(b=>b.y+=b.dy*dt);playerBullets.splice(0,playerBullets.findIndex(b=>b.y+b.h<0)+1);enemyBullets.splice(0,enemyBullets.findIndex(b=>b.y>H)+1);let blockLeft=W,blockRight=0,blockBottom=0;enemies.forEach(e=>{blockLeft=Math.min(blockLeft,e.x);blockRight=Math.max(blockRight,e.x+e.w);blockBottom=Math.max(blockBottom,e.y+e.h);});if(blockRight+enemyDir*enemySpeed*dt>W||blockLeft+enemyDir*enemySpeed*dt<0){enemyDir*=-1;enemies.forEach(e=>e.y+=enemyDescend);}enemies.forEach(e=>e.x+=enemyDir*enemySpeed*dt);enemyFireTimer+=dt;if(enemyFireTimer>1){enemyFireTimer=0;if(enemies.length){const shooter=enemies[Math.floor(Math.random()*enemies.length)];enemyBullets.push({x:shooter.x+shooter.w/2-2,y:shooter.y+shooter.h,w:4,h:10,dy:200});}} // collisions player bullets vs enemies for(let i=playerBullets.length-1;i>=0;i--){let b=playerBullets[i];let hit=-1;for(let j=0;j<enemies.length;j++){let e=enemies[j];if(b.x<b.x+ b.w && b.x+b.w>e.x && b.y<b.y+b.h && b.y+b.h>e.y){hit=j;break;}}if(hit>=0){explosions.push({x:enemies[hit].x+enemies[hit].w/2,y:enemies[hit].y+enemies[hit].h/2,life:0.3});enemies.splice(hit,1);playerBullets.splice(i,1);score+=10;}} // enemy bullets vs player for(let i=enemyBullets.length-1;i>=0;i--){let b=enemyBullets[i];if(b.x<b.x+b.w && b.x+b.w>player.x && b.y<b.y+b.h && b.y+b.h>player.y){explosions.push({x:player.x+player.w/2,y:player.y+player.h/2,life:0.5});gameOver=true;break;}} // enemy reach bottom if(blockBottom>=player.y){gameOver=true;} // update explosions for(let i=explosions.length-1;i>=0;i--){explosions[i].life-=dt;if(explosions[i].life<=0)explosions.splice(i,1);} if(!gameOver && enemies.length===0){level++;initEnemies();} }function draw(){ctx.clearRect(0,0,W,H); // player ctx.fillStyle='white';ctx.fillRect(player.x,player.y,player.w,player.h); // player bullets ctx.fillStyle='lime';playerBullets.forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h)); // enemies ctx.fillStyle='red';enemies.forEach(e=>ctx.fillRect(e.x,e.y,e.w,e.h)); // enemy bullets ctx.fillStyle='orange';enemyBullets.forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h)); // explosions ctx.fillStyle='yellow';explosions.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,15* (p.life/0.5),0,2*Math.PI);ctx.fill();}); // UI ctx.fillStyle='white';ctx.font='16px monospace';ctx.fillText('Score: '+score,10,20);ctx.fillText('Level: '+level,10,40); if(gameOver){ctx.fillStyle='white';ctx.font='48px monospace';ctx.fillText('GAME OVER',W/2-150,H/2); } }function loop(timestamp){let dt=(timestamp-lastTime)/1000;lastTime=timestamp;update(dt);draw();if(!gameOver)animationId=requestAnimationFrame(loop);}initEnemies();requestAnimationFrame(loop);}

Solution B: ```javascript
function createSpaceInvadersGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    let player = { x: 250, y: 450, width: 20, height: 20, speed: 5 };
    let enemies = [];
    let bullets = [];
    let score = 0;
    let level = 1;
    let gameRunning = true;
    let enemySpeed = 1;
    let enemyShootInterval = 2000;

    function initEnemies() {
        for (let i = 0; i < 5; i++) {
            for (let j = 0; j < 10; j++) {
                enemies.push({ x: j * 40 + 20, y: i * 30 + 20, width: 20, height: 20, health: 3 });
            }
        }
    }

    function drawPlayer() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(player.x, player.y, player.width, player.height);
    }

    function drawEnemies() {
        enemies.forEach(enemy => {
            if (enemy.health > 0) {
                ctx.fillStyle = 'red';
                ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
            }
        });
    }

    function drawBullets() {
        bullets.forEach(bullet => {
            ctx.fillStyle = 'white';
            ctx.fillRect(bullet.x, bullet.y, bullet.width, bullet.height);
        });
    }

    function updatePlayerPosition() {
        if (keys['ArrowLeft'] && player.x > 0) {
            player.x -= player.speed;
        }
        if (keys['ArrowRight'] && player.x < canvas.width - player.width) {
            player.x += player.speed;
        }
    }

    function shootBullet() {
        if (!gameRunning) return;
        bullets.push({ x: player.x + player.width / 2, y: player.y, width: 5, height: 10, speed: -7 });
    }

    function updateBullets() {
        bullets.forEach((bullet, index) => {
            bullet.y += bullet.speed;
            if (bullet.y < 0) {
                bullets.splice(index, 1);
            }
        });
    }

    function checkCollisions() {
        bullets.forEach((bullet, bIndex) => {
            enemies.forEach((enemy, eIndex) => {
                if (bullet.x < enemy.x + enemy.width &&
                    bullet.x + bullet.width > enemy.x &&
                    bullet.y < enemy.y + enemy.height &&
                    bullet.y + bullet.height > enemy.y) {
                    enemy.health--;
                    bullets.splice(bIndex, 1);
                    if (enemy.health <= 0) {
                        enemies.splice(eIndex, 1);
                        score++;
                    }
                }
            });

            if (player.x < enemy.x + enemy.width &&
                player.x + player.width > enemy.x &&
                player.y < enemy.y + enemy.height &&
                player.y + player.height > enemy.y) {
                gameRunning = false;
            }
        });
    }

    function moveEnemies() {
        enemies.forEach(enemy => {
            enemy.x += enemySpeed;
        });

        if (enemies.some(enemy => enemy.x >= canvas.width - enemy.width || enemy.x <= 0)) {
            enemies.forEach(enemy => enemy.y += 10);
            enemySpeed *= -1;
        }
    }

    function enemyShoots() {
        if (Math.random() < 0.01 && enemies.length > 0) {
            const randomEnemy = Math.floor(Math.random() * enemies.length);
            bullets.push({ x: enemies[randomEnemy].x + enemies[randomEnemy].width / 2, y: enemies[randomEnemy].y + enemies[randomEnemy].height, width: 5, height: 10, speed: 7 });
        }
    }

    function updateScore() {
        ctx.font = '20px Arial';
        ctx.fillStyle = 'black';
        ctx.fillText(`Score: ${score}`, 10, 30);
    }

    function checkWinLose() {
        if (enemies.length === 0) {
            level++;
            initEnemies();
            enemySpeed += 1;
            enemyShootInterval -= 500;
        }
        if (enemies.some(enemy => enemy.y >= canvas.height - enemy.height) || !gameRunning) {
            gameRunning = false;
            ctx.font = '30px Arial';
            ctx.fillStyle = 'black';
            ctx.fillText('Game Over', 150, 250);
        }
    }

    function gameLoop() {
        if (!gameRunning) return;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        drawPlayer();
        drawEnemies();
        drawBullets();

        updatePlayerPosition();
        updateBullets();
        checkCollisions();
        moveEnemies();
        enemyShoots();
        updateScore();
        checkWinLose();

        requestAnimationFrame(gameLoop);
    }

    let keys = {};
    window.addEventListener('keydown', event => {
        keys[event.key] = true;
        if (event.key === ' ') {
            shootBullet();
        }
    });

    window.addEventListener('keyup', event => {
        keys[event.key] = false;
    });

    initEnemies();
    gameLoop();
}
